def roman_to_int(s):
    """Convert a Roman numeral (1..3999, subtractive form) to an int."""
    total = 0
    for i, ch in enumerate(s):
        v = _VALUES[ch]
        if i + 1 < len(s) and v < _VALUES[s[i + 1]]:
            total -= v
        else:
            total += v
    return total

